import java.util.*;
import java.io.*;

public class Main {
    static class Step implements Comparable<Step> {
        long val;
        int cost;

        Step(long val, int cost) {
            this.val = val;
            this.cost = cost;
        }

        @Override
        public int compareTo(Step other) {
            return Integer.compare(other.cost, this.cost);
        }
    }

    static Set<Long> visitedNodes = new HashSet<>();

    static boolean visitedAlready(long c) {
        return visitedNodes.contains(c);
    }

    static Step computeUupper(long n) {
        long res = 0;
        int digitsCount = 0;
        while (res < n) {
            res = res * 10 + 1;
            digitsCount++;
        }
        return new Step(res, digitsCount);
    }

    static Step computeUpperLimit(long n) {
        long res = 0;
        int digitsCount = 0;
        while (res * 10 + 1 <= n) {
            res = res * 10 + 1;
            digitsCount++;
        }
        long baseRes = res;
        int baseDigits = digitsCount;
        while (res < n) {
            res += baseRes;
            digitsCount += baseDigits;
        }
        return new Step(res, digitsCount);
    }

    static Step computeLowerLimit(long n) {
        long res = 0;
        int digitsCount = 0;
        while (res * 10 + 1 <= n) {
            res = res * 10 + 1;
            digitsCount++;
        }
        long baseRes = res;
        int baseDigits = digitsCount;
        while (res + baseRes <= n) {
            res += baseRes;
            digitsCount += baseDigits;
        }
        return new Step(res, digitsCount);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine());

        PriorityQueue<Step> pq = new PriorityQueue<>();
        pq.add(new Step(n, 0));

        while (pq.peek().val != 0) {
            Step current = pq.poll();
            long currentVal = current.val;
            int currentCost = current.cost;

            if (visitedAlready(currentVal))
                continue;
            visitedNodes.add(currentVal);

            for (Step s : Arrays.asList(computeLowerLimit(currentVal), computeUpperLimit(currentVal), computeUupper(currentVal))) {
                s.cost += currentCost;
                s.val = Math.abs(currentVal - s.val);
                pq.add(s);
            }
        }

        System.out.println(pq.peek().cost);
    }
}
